pageRules:
@media print {
  @page report { size: a4; margin: 12mm; }
  .app:has(.report-print) { page: report; min-height: 0px; display: block !important; }
  .app:has(.report-print) .page-heading, .app:has(.report-print) .shift-bar, .app:has(.report-print) .sidebar, .app:has(.report-print) header, .notice, .report-controls, .report-print .button, .report-print .category-tabs { display: none !important; }
  .app:has(.report-print) .workspace { margin: 0px; width: 100%; }
  .app:has(.report-print) .workspace main { padding: 0px; max-width: none; }
  .report-print { page: report; }
  .report-print .panel { break-inside: avoid; border: 0px; }
  .report-print .split { display: block; }
  .report-print .chart { margin-bottom: 20px; }
}

@media print {
  @page { size: 80mm 200mm; margin: 2mm; }
  body { background: white; }
  .app, .print-actions, nextjs-portal { display: none !important; }
  .print-overlay { position: static; background: white; padding: 0px; display: block; }
  .print-document { width: 72mm; padding: 0px; font-size: 10px; }
  .print-document img { width: 46mm; height: 46mm; }
  .print-document h2 { font-size: 14px; }
  @page qr-card { size: 80mm 120mm; margin: 4mm; }
  @page receipt { size: 80mm 200mm; margin: 4mm; }
  .receipt-print-overlay { page: receipt; width: 72mm; margin: 0px auto; }
  .print-document.receipt { width: 72mm; padding: 0px; margin: 0px auto; }
  .qr-print-overlay { page: qr-card; width: 72mm; margin: 0px auto; }
  .print-document.qr-card { width: 72mm; min-height: 112mm; padding: 0px; margin: 0px auto; break-inside: avoid; }
  .print-document.qr-card-customer { height: 112mm; }
}
